import * as THREE from './three.module.min.js';
import * as BufferGeometryUtils from './BufferGeometryUtils.js';
import { FontLoader } from './FontLoader.js';

const mainRenderer = new THREE.WebGLRenderer({ antialias: true, powerPreference: "high-performance" });
mainRenderer.setPixelRatio(window.devicePixelRatio);
document.body.appendChild(mainRenderer.domElement);
const mainScene = new THREE.Scene();
const mainCamera = new THREE.PerspectiveCamera(50, document.documentElement.clientWidth / document.documentElement.clientHeight, 0.1, 20);
const ambientLight = new THREE.AmbientLight(0xFFFFFF, 0.8);
const directionalLight = new THREE.DirectionalLight(0xFFFFFF, 1);
directionalLight.position.set(-1, 1, 1);
const button = [];
const topContainer = new THREE.Object3D();
const bottomContainer = new THREE.Object3D();
mainScene.add(ambientLight, directionalLight, topContainer, bottomContainer);
mainScene.background = new THREE.Color(0x000000);
mainScene.fog = new THREE.Fog(0x000000, 5, 20);
let oldWindow;
onWindowResize();
function onWindowResize() {
	(document.body.clientHeight / document.body.clientWidth >= 1.5) ? mainCamera.fov = (Math.atan((document.body.clientHeight / 2) / ((document.body.clientWidth / 2) / (Math.tan(50 * Math.PI / 360) / 1.5)))) * 360 / Math.PI : mainCamera.fov = 52;
  topContainer.position.y = Math.tan(mainCamera.fov * Math.PI / 360);
  bottomContainer.position.y = -Math.tan(mainCamera.fov * Math.PI / 360);
  if (button.length > 0) {
  	if (onMain) ui.moneyCount.position.x = -(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.06;
    if (onPlay && ui.fade.material.opacity === 0) {
     	button[4].position.set(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth - 0.06, button[4].position.y, -1);
    }
    if (onPlayUI) {
      ui.moneyCount.countText.geometry.computeBoundingBox();
      ui.moneyCount.gameAnchor = -(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.06 - ui.moneyCount.countText.geometry.boundingBox.max.x * 0.08;
      ui.moneyCount.position.x = -(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.06 - ui.moneyCount.countText.geometry.boundingBox.max.x * 0.08;
      ui.enemiesCount.position.set(-(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.095, -0.155, -1);
    }
    ui.heartButton.position.set(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth - 0.13, -0.18, -1);
    ui.adButton.position.set(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth - 0.13, -0.18, -1);
    if (onDeathScreen) ui.moneyCount.position.x = -(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.06;
    button[22].position.set(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth - 0.07, -0.06, -1);
    ui.livesContainer.position.x = -(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.07;
  }
	mainCamera.aspect = document.body.clientWidth / document.body.clientHeight;
	mainCamera.updateProjectionMatrix();
	mainRenderer.setSize(document.body.clientWidth, document.body.clientHeight);
	oldWindow = document.body.clientWidth / document.body.clientHeight;
}


let preloadingCount = 2;
let config = document.createElement('script');
config.src = "./js/config.js";
document.head.append(config);
config.onload = () => {
  onWindowResize();
	preloadingCount ? preloadingCount-- : showLoadingScreen();
};
let tex = [];
for (let i = 0; i < 2; i++) {
  loadPIC(`textures/tex${i}.png`).then(texture => {
  	tex[i] = texture;
  	tex[i].colorSpace = THREE.SRGBColorSpace;
  	preloadingCount ? preloadingCount-- : showLoadingScreen();
  });
}
function loadPIC(url) { return new Promise(resolve => { new THREE.TextureLoader().load(url, resolve) }) }
const preloadingGraphics = {};
let onLoading = false;
const IS_DEBUG = false; // для локальных тестов ставим в true!

function initHeroData(data) {

  // heroData = data;
  const count = 13;

  for (let i = 0; i < heroData.length; i++) {
    const hd = heroData[i];
    hd.currentColor = data[i * count];
    hd.currentSpeed = data[i * count + 1];
    hd.currentMagnet = data[i * count + 2];
    hd.currentPower = data[i * count + 3];
    
    hd.speedPrice = data[i * count + 4];
    hd.powerPrice = data[i * count + 5];
    hd.magnetPrice = data[i * count + 6];
    hd.price.sum = data[i * count + 7];

    for (let j = 0; j < 5; j++)
    {
      hd.colorPrice[j].sum = data[i * count + 8 + j]
    }
  }
}

function saveHeroData() {

  // return heroData;

  const data = [];
  for (let i = 0; i < heroData.length; i++) {
    const hd = heroData[i];
    data.push(
      hd.currentColor,
      hd.currentSpeed,
      hd.currentMagnet,
      hd.currentPower,

      hd.speedPrice, 
      hd.powerPrice, 
      hd.magnetPrice,
      hd.price.sum
    );

    for (let j = 0; j < 5; j++)
    {
      data.push(hd.colorPrice[j].sum);
    }
  }

  return data;
}

const sdk = new Social(IS_DEBUG);
window.sdk = sdk;
async function showLoadingScreen() {
	preloadingGraphics.back = new THREE.Mesh(new THREE.PlaneGeometry(739, 182), new THREE.MeshBasicMaterial({ map: tex[0], transparent: true, opacity: 0 }));
  preloadingGraphics.back.scale.set(0.00025, 0.00025, 1);
  preloadingGraphics.back.position.set(0, 0.02, -0.5);
  preloadingGraphics.bar = new THREE.Mesh(new THREE.PlaneGeometry(739, 182), new THREE.MeshBasicMaterial({ map: tex[1], transparent: true }));
  preloadingGraphics.bar.geometry.translate(369.5, 0, 0);
  preloadingGraphics.bar.scale.set(0, 0.00025, 1);
  preloadingGraphics.bar.position.set(-369.5 * 0.00025, 0.02, -0.4999);
  mainScene.add(preloadingGraphics.back, preloadingGraphics.bar);
  gsap.to(preloadingGraphics.back.material, { duration: 0.2, opacity: 1, ease: "power1.inOut", onComplete: async () => {
  	onWindowResize();
      sdk.initialize().then(() => {
        sdk.load().then((data) => {
          if (data) {
            saveData = data;
            chosenHero = saveData.chosenHero;
            
            currentLevel = saveData.currentLevel;
            moneyCount = saveData.moneyCount;
            
            // heroData = saveData.heroData;
            initHeroData(saveData.heroData)
            levelData = saveData.levelData;
          } else { }
          if (currentLevel > 0) {
            onHint = false;
            onBossHint = false;
          }
          currentLang = sdk.lang == "ru" ? 0 : 1;
          sdk.loadingStart();
          
          goLoad();
        });
      });
  } });
}
