function hideLoadingScreen() {
	mainScene.remove(preloadingGraphics.back);
  gsap.to(preloadingGraphics.bar.material, { duration: 0.2, opacity: 0, ease: "power1.inOut", onComplete() {
  	mainScene.remove(preloadingGraphics.bar);
  } });

  sdk.loadingStop();

	showStartScreen();
}
