function showButton(object, color, blimColor) {
  for (let i = 0; i < object.part.length; i++) {
    object.part[i].material.color.setHex(randomColor[Math.floor(Math.random() * 6)]);
    object.part[i].position.x = 0.015 - 0.03 * object.part.length / 2 + 0.03 * i;
    gsap.to(object.part[i].scale, { duration: 0.2 + 0.6 / (i + 1), x: 1, y: 1, ease: "power1.inOut" });
    gsap.from(object.part[i].position, { duration: 0.2 + 0.6 / (i + 1), x: object.part[i].position.x - 0.3 / (i + 1), ease: "power1.out" });
    gsap.to(object.part[i].material.color, { duration: 0.2 + 0.6 / (i + 1), r: color.r, g: color.g, b: color.b, ease: "power1.in" });
  }
  gsap.to(object.text.scale, { duration: 0.3, y: 1, ease: "back.out", delay: 0.3 });
  gsap.to(object.text.scale, { duration: 0.5, x: 1, ease: "back.out", delay: 0.3 });
  gsap.from(object.position, { duration: 0.8, x: -0.3, ease: "back.out", onComplete: () => {
    object.ready = true;
    if (blimColor) blimButton(object, color, blimColor);
  } });
}
function blimButton(object, mainColor, blimColor) {
  for (let i = 0; i < object.part.length; i++) {
    if (object.part[i].colorTween !== undefined && object.part[i].colorTween !== null) {
      object.part[i].colorTween.kill();
      object.part[i].colorTween = null;
      object.part[i].scaleTween.kill();
      object.part[i].scaleTween = null;
    }
    object.part[i].colorTween = gsap.fromTo(object.part[i].material.color, { r: mainColor.r, g: mainColor.g, b: mainColor.b }, { duration: 0.4, r: blimColor.r, g: blimColor.g, b: blimColor.b, ease: "power1.inOut", repeat: 1, yoyo: true, delay: 0.03 * i });
    object.part[i].scaleTween = gsap.fromTo(object.part[i].scale, { x: 1, y: 1 }, { duration: 0.4, x: 0.9, y: 0.9, ease: "power1.out", repeat: 1, yoyo: true, delay: 0.03 * i });
  }
  setTimeout(() => {
    if (object.ready) {
      blimButton(object, mainColor, blimColor)
    }
  }, 3000);
}
function clickButton(object, color, blimColor, func) {
  blockButton = true;
  const u2 = atlas.play('u2');
  atlas.volume(0.55, u2);
  for (let i = 0; i < object.part.length; i++) {
    if (object.part[i].colorTween !== undefined && object.part[i].colorTween !== null) {
      object.part[i].colorTween.kill();
      object.part[i].colorTween = null;
      object.part[i].scaleTween.kill();
      object.part[i].scaleTween = null;
    }
    gsap.to(object.part[i].material.color, { duration: 0.1, r: blimColor.r, g: blimColor.g, b: blimColor.b, ease: "power2.out", delay: 0.01 * i });
    gsap.to(object.part[i].scale, { duration: 0.1, x: 0.8, y: 0.8, ease: "power2.out", delay: 0.01 * i, onComplete: () => {
      gsap.to(object.part[i].material.color, { duration: 0.1, r: color.r, g: color.g, b: color.b, ease: "power3.in", delay: 0.01 * i });
      gsap.to(object.part[i].scale, { duration: 0.1, x: 1, y: 1, ease: "power3.in", delay: 0.01 * i });
    } });
  }

  gsap.to(object.text.scale, { duration: 0.1, x: 0.8, y: 0.8, ease: "power2.out", onComplete: () => {
    gsap.to(object.text.scale, { duration: 0.1 + 0.02 * (object.part.length - 1), x: 1, y: 1, ease: "power2.in", onComplete: () => {
      for (let i = 0; i < object.part.length; i++) {
        gsap.to(object.part[i].scale, { duration: 0.1 + 0.4 / (i + 1), x: 0.3, y: 0, ease: "power1.in" });
        gsap.to(object.part[i].position, { duration: 0.1 + 0.4 / (i + 1), x: object.part[i].position.x + 0.2, ease: "power1.in" });
        const randomNum = Math.floor(Math.random() * 6);
        gsap.to(object.part[i].material.color, { duration: 0.1 + 0.4 / (i + 1), r: randomThreeColor[randomNum].r, g: randomThreeColor[randomNum].g, b: randomThreeColor[randomNum].b, ease: "power1.in" });
      }
      gsap.to(object.text.scale, { duration: 0.1, x: 0, y: 0, ease: "power2.out" });

      if (func) func();
    } });
  } });
}
