	mainScene.background.setHex(arenaColors[arenaSetting][arenaColor][4]);
	mainScene.fog.color.setHex(arenaColors[arenaSetting][arenaColor][4]);
	let numberOfArenas = 1;
	if (levelData.numberOfArenas > 0) {
		numberOfArenas = levelData.numberOfArenas;
	} else {
  	if (currentLevel <= arenasRange.levelMax) {
	  	if (currentLevel <= arenasRange.levelMid) {
		  	if (Math.random() < arenasRange.twoArenasMinChance + (arenasRange.twoArenasMidChance - arenasRange.twoArenasMinChance) * (currentLevel / arenasRange.levelMid)) numberOfArenas = 2;
		  	if (Math.random() < arenasRange.threeArenasMinChance + (arenasRange.threeArenasMidChance - arenasRange.threeArenasMinChance) * (currentLevel / arenasRange.levelMid)) numberOfArenas = 3;
   		} else {
		  	if (Math.random() < arenasRange.twoArenasMidChance + (arenasRange.twoArenasMaxChance - arenasRange.twoArenasMidChance) * ((currentLevel - arenasRange.levelMid) / (arenasRange.levelMax - arenasRange.levelMid))) numberOfArenas = 2;
		  	if (Math.random() < arenasRange.threeArenasMidChance + (arenasRange.threeArenasMaxChance - arenasRange.threeArenasMidChance) * ((currentLevel - arenasRange.levelMid) / (arenasRange.levelMax - arenasRange.levelMid))) numberOfArenas = 3;
	  	}
  	} else {
	  	if (Math.random() < arenasRange.twoArenasMaxChance) numberOfArenas = 2;
	  	if (Math.random() < arenasRange.twoArenasMaxChance) numberOfArenas = 3;
  	}
	}
//	numberOfArenas = 2
