          let shape = new THREE.Shape();
          shape.moveTo(-0.013, 0);
          shape.lineTo(-0.012, 0.002);
          shape.lineTo(-0.012 + 0.025 * scale.step, 0.002 + 0.002 * scale.step);
          shape.lineTo(-0.013 + 0.025 * scale.step, 0);
          ui.heroCount.foodBar.geometry = new THREE.ShapeGeometry(shape, 1);
