function takeCoin(chosen, speed) {
  if (!isClear) atlas.play("22");
	coin[chosen].ready = 0;
	if (coin[chosen].rotTween !== undefined && coin[chosen].rotTween !== null) {
  	coin[chosen].rotTween.kill();
  	coin[chosen].rotTween = null;
	}
	if (coin[chosen].scale.x == 0.6) {
		levelMoney += coinValue[0];
	} else if (coin[chosen].scale.x == 0.7) {
		levelMoney += coinValue[1];
	} else {
		levelMoney += coinValue[2];
	}
  coin[chosen].posX = coin[chosen].position.x;
  coin[chosen].posY = coin[chosen].position.y;
  coin[chosen].posZ = coin[chosen].position.z;
  coin[chosen].startScale = coin[chosen].scale.x;
  gsap.to(coin[chosen].scale, { duration: 0.15 + speed, x: 0, y: 0, z: 0, ease: "power2.in", onUpdate() {
    coin[chosen].position.set(coin[chosen].posX - (coin[chosen].posX + gameContainer.levelContainer.position.x) * (coin[chosen].startScale - coin[chosen].scale.x), coin[chosen].posY + (0.3 + 0.3 * hero[chosenHero].scale.x) * (coin[chosen].startScale - coin[chosen].scale.x), coin[chosen].posZ - (coin[chosen].posZ + gameContainer.levelContainer.position.z) * (coin[chosen].startScale - coin[chosen].scale.x));
  }, onComplete: () => {
    coin[chosen].ready = -1;
  	coin[chosen].visible = false;
  } });
  ui.moneyCount.countText.geometry.dispose();
  ui.moneyCount.countText.geometry = new THREE.ShapeGeometry(Slackey.generateShapes(`${levelMoney}`, 0.08), 2);
  ui.moneyCount.countText.geometry.computeBoundingBox();
  ui.moneyCount.gameAnchor = -(Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.06 - ui.moneyCount.countText.geometry.boundingBox.max.x * 0.08;
  gsap.to(ui.moneyCount.position, { duration: 0.1, x: (-Math.tan(mainCamera.fov * Math.PI / 360) / document.body.clientHeight * document.body.clientWidth) + 0.06 - ui.moneyCount.countText.geometry.boundingBox.max.x * 0.08, delay: speed, ease: "power1.inOut" });
  ui.moneyCount.countText.geometry.dispose();
  ui.moneyCount.countText.geometry = new THREE.ShapeGeometry(Slackey.generateShapes(`${ui.moneyCount.currentCount}`, 0.08), 2);
  let addMoney = { count: ui.moneyCount.currentCount };
  ui.moneyCount.currentCount = levelMoney;
  gsap.to(addMoney, { duration: 0.3, count: levelMoney, ease: "none", delay: speed, onUpdate() {
    ui.moneyCount.countText.geometry.dispose();
    ui.moneyCount.countText.geometry = new THREE.ShapeGeometry(Slackey.generateShapes(`${Math.round(addMoney.count)}`, 0.08), 2);
  } });
  gsap.to(ui.moneyCount.scale, { duration: 0.15, x: 0.6, y: 0.6, ease: "power1.inOut", repeat: 1, yoyo: true, delay: speed });
  for (let i = 0; i < 12; i++) {
    const random = 0.2 + Math.random() * 0.2;
    const randomScale = 0.3 + Math.random() * 0.2;
   	gsap.fromTo(ui.moneyCount.sparkle[i].position, { x: 0, y: 0 }, { duration: random, x: -0.2 + Math.random() * 0.4, y: -0.2 + Math.random() * 0.4, ease: "power1.out" });
    gsap.fromTo(ui.moneyCount.sparkle[i].scale, { x: 0, y: 0 }, { duration: random * 0.5, x: randomScale, y: randomScale, ease: "power1.out", repeat: 1, yoyo: true });
  	ui.moneyCount.add(ui.moneyCount.sparkle[i]);
  }
}
