    object.moveTween[10] = gsap.to(object.children[1].rotation, { duration: randomTime * 0.4, x: 0.4 * firstLeg, ease: "power1.out", repeat: 1, yoyo: true });
    object.moveTween[11] = gsap.to(object.children[2].rotation, { duration: randomTime * 0.4, x: -0.4 * firstLeg, ease: "power1.out", repeat: 1, yoyo: true });
