function clearHeroAnimation(object) {
	while (object.moveTween.length > 0) {
		object.moveTween[object.moveTween.length - 1].kill();
		object.moveTween[object.moveTween.length - 1] = null;
		object.moveTween.pop();
	}
}
function turnEnemy(object, boxSide) {
	object.meetObstacle = true;
	if (!object.onTurn) {
	  if (boxSide == "x") {
		  if ((object.rotation.y % Math.PI >= 0 && object.rotation.y % Math.PI < Math.PI * 0.5) || (object.rotation.y % Math.PI <= -Math.PI * 0.5 && object.rotation.y % Math.PI > -Math.PI)) {
		  	object.avoidAngle = 1;
		  } else {
		  	object.avoidAngle = -1;
	  	}
  	} else {
	  	if ((object.rotation.y % Math.PI >= 0 && object.rotation.y % Math.PI < Math.PI * 0.5) || (object.rotation.y % Math.PI <= -Math.PI * 0.5 && object.rotation.y % Math.PI > -Math.PI)) {
		  	object.avoidAngle = -1;
		  } else {
		  	object.avoidAngle = 1;
	  	}
  	}
  	object.onTurn = true;
	}
  if (object.children[0].turnTween !== undefined && object.children[0].turnTween !== null) {
  	object.children[0].turnTween.kill();
  	object.children[0].turnTween = null;
  }
  object.children[0].turnTween = gsap.fromTo(object.rotation, { y: object.rotation.y }, { duration: object.children[0].moveSpeed, y: () => { return object.rotation.y - Math.PI * 0.25 * object.avoidAngle }, ease: "power1.inOut", onComplete: () => {
  	object.children[0].turnTween.kill();
  	object.children[0].turnTween = null;
  	object.meetObstacle = false;
  	object.children[0].turnTween = gsap.to(object.rotation, { duration: 0.5, y: object.rotation.y, ease: "none", onComplete: () => {
      object.children[0].turnTween.kill();
      object.children[0].turnTween = null;
  	  object.onTurn = false;
  	} });
  } });
}
function respawnEnemy() {
	if (currentArena < gameContainer.arena.length) {
		if (onControl) {
	    for (let i = 0; i < npc.length; i++) {
        if (npc[i].event == "respawnReady" && npc[i].arena == currentArena) {
          npc[i].event = "onRespawn";
          for (let k = 0; k < 50; k++) {
           	let spotFree = true;
            const respawnPos = [-4 + 8 * Math.random(), -4 + 8 * Math.random() + gameContainer.arena[npc[i].arena].position.z];
            if (Math.abs(respawnPos[0] + gameContainer.levelContainer.position.x) < 1.8 + 0.7 * hero[chosenHero].scale.x ** 1.45 && Math.abs(respawnPos[1] + gameContainer.levelContainer.position.z) < 1.8 + 0.7 * hero[chosenHero].scale.x ** 1.45 + 1) spotFree = false;
            if (spotFree) {
      	      for (let j = 0; j < npc.length; j++) {
      	    	  if (Math.abs(npc[j].position.x - respawnPos[0]) < 1.4 + 0.7 * npc[j].scale.x ** 1.45 && Math.abs(npc[j].position.z - respawnPos[1]) < 1.4 + 0.7 * npc[j].scale.x ** 1.45 + 1) {
      		      	spotFree = false;
      		      	break;
      	      	}
            	}
            }
            if (spotFree) {
              for (let j = 0; j < food.length; j++) {
        	      if (food[j].ready >= 0 && Math.abs(food[j].position.x - respawnPos[0]) < npc[i].size && Math.abs(food[j].position.z - respawnPos[1]) < npc[i].size) {
        		      spotFree = false;
        	       	break;
              	}
              }
              for (let j = 0; j < coin.length; j++) {
            	  if (coin[j].visible && Math.abs(respawnPos[0] - coin[j].position.x) < 0.6 && Math.abs(respawnPos[1] - coin[j].position.z) < 0.8) {
          	    	spotFree = false;
          	    	break;
              	}
              }
              for (let j = 0; j < basicBonus.length; j++) {
              	if (basicBonus[j].ready >= 0 && Math.abs(respawnPos[0] - basicBonus[j].position.x) < 1.4 && Math.abs(respawnPos[1] - basicBonus[j].position.z) < 1.4) {
          	    	spotFree = false;
          	    	break;
            	  }
              }
              for (let j = 0; j < videoBonus.length; j++) {
          	    if (videoBonus[j].ready >= 0 && Math.abs(respawnPos[0] - videoBonus[j].position.x) < 1.4 && Math.abs(respawnPos[1] - videoBonus[j].position.z) < 1.4) {
          	    	spotFree = false;
          	    	break;
              	}
              }
              if (gameContainer.bonusHeart.ready && Math.abs(respawnPos[0] - gameContainer.bonusHeart.position.x) < 1.4 && Math.abs(respawnPos[1] - gameContainer.bonusHeart.position.z) < 1.4) {
               	spotFree = false;
              }
              for (let j = 0; j < bomb.length; j++) {
              	if (bomb[j].ready >= 0 && Math.abs(respawnPos[0] - bomb[j].position.x) < 0.8 && Math.abs(respawnPos[1] - bomb[j].position.z) < 0.8) {
          	    	spotFree = false;
          	    	break;
              	}
              }
            }
            if (spotFree) {
            	gameContainer.respawn.position.set(respawnPos[0], -0.299, respawnPos[1]);
            	gameContainer.respawn.visible = true;
            	for (let j = 0; j < 24; j++) {
         	    	const tempRandom = 0.2 + Math.random() * 0.3;
         	    	const randomDelay = Math.random() * 0.3;
        	      gameContainer.respawn.sparkle[j].position.y = 0;
        	    	gsap.to(gameContainer.respawn.sparkle[j].scale, { duration: tempRandom, x: 0.8, y: 0.8, ease: "power1.inOut", repeat: 1, yoyo: true, delay: randomDelay });
        	    	gsap.to(gameContainer.respawn.sparkle[j].position, { duration: tempRandom * 2, y: 0.5 + Math.random() * 3, ease: "power1.in", delay: randomDelay });
            	}
            	npc[i].idleAnimation(npc[i].children[0]);
            	npc[i].position.set(respawnPos[0], 0, respawnPos[1]);
            	npc[i].rotation.y = -Math.PI + Math.random() * Math.PI * 2;
              npc[i].meetObstacle = false;
              let respawnLives = 0;
              let npcCount = 0;
              for (let i = 0; i < npc.length; i++) {
              	if (npc[i].arena == currentArena && npc[i].powerCount > 0) {
        	      	respawnLives += npc[i].powerCount;
          	  	  npcCount++;
               	}
              }
              if (npcCount == 0) npcCount = 1;
              npc[i].powerCount = Math.ceil(respawnLives / npcCount);
              if (hero[chosenHero].powerCount > npc[i].powerCount) {
              	npc[i].powerCount += Math.floor(Math.random() * (hero[chosenHero].powerCount - npc[i].powerCount));
              }
              if (npc[i].powerCount <= 0) npc[i].powerCount = Math.ceil(hero[chosenHero].powerCount * 0.5 + Math.random() * hero[chosenHero].powerCount * 0.5);
              if (npc[i].powerCount < 1) npc[i].powerCount = 1;
              npc[i].coinValue = npc[i].powerCount;
              if (onControl) atlas.play("10");
              growEnemy(i);
            	gsap.to(npc[i].children[1].position, { duration: 0.04, z: 0, ease: "none", repeat: 15, yoyo: true, delay: 0.2, onRepeat: () => {
  	          	npc[i].children[0].visible ? npc[i].children[0].visible = false : npc[i].children[0].visible = true;
  	          }, onComplete: () => {
  	          	npc[i].children[0].visible = true;
  	   	        npc[i].children[1].children[0].geometry.dispose();
	              npc[i].children[1].children[0].geometry = new THREE.ShapeGeometry(Slackey.generateShapes(`${npc[i].powerCount}`, 0.2), 2);
  	            npc[i].children[1].children[0].geometry.center();
      	        npc[i].children[1].children[0].position.y = 0;
      	        npc[i].children[1].children[0].visible = true;
      	        npc[i].children[1].children[1].visible = false;
                npc[i].children[1].children[2].visible = false;
                npc[i].children[1].children[3].visible = false;
                npc[i].children[1].position.y = 1.32;
                npc[i].children[1].children[0].material = enemyCounterMaterial[arenaSetting];
                gsap.to(npc[i].children[1].scale, { duration: 0.15, x: 1, y: 1, z: 1, ease: "back.out" });
  	          	npc[i].walkAnimation(npc[i].children[0]);
             	} });
            	gsap.to([gameContainer.respawn.ring_1.scale, gameContainer.respawn.ring_2.scale], { duration: 0.65, x: 1, z: 1, ease: "back.out", repeat: 1, yoyo: true, onComplete: () => {
        	    	gameContainer.respawn.visible = false;
            	} });
            	break;
            } else {
            	npc[i].event = "respawnReady";
            }
          }
      	  break;
        }
    	}
		}
		if (dropReady) {
  	  setTimeout(() => {
		    if (dropReady) { 
		      respawnEnemy();
		    } else {
		      onRespawnEnemy = false;
		    }
  	  }, 2000);
		} else {
		  onRespawnEnemy = false;
		}
  }
}
