  	    ui.bossHint.hand_2.visible = false;
    	  ui.bossHint.hand_1.visible = false;
  	    ui.bossHint.hand_1.scale.set(0, 0, 1);
  	    ui.bossHint.hand_2.scale.set(0, 0, 1);
