function endFight() {
	gsap.to([ui.finalCount.position, ui.bossCount.position], { duration: 0.3, y: 0.05, ease: "power2.in" });
  gsap.to([ui.finalCount.scale, ui.bossCount.scale], { duration: 0.3, x: 0, y: 0, ease: "back.in" });
  if (onBossHint) {
    onBossHint = false;
  	ui.bossHint.scaleTween.kill();
  	ui.bossHint.scaleTween = null;
  	ui.bossHint.opacityTween.kill();
  	ui.bossHint.opacityTween = null;
  	gsap.to(ui.mouseHint.lmb.material, { duration: 0.3, opacity: 0, ease: "power1.in" });
  	gsap.to([ui.bossHint.hand_1.scale, ui.bossHint.hand_1.scale, ui.bossHint.ring.scale], { duration: 0.3, x: 0, y: 0, ease: "power2.in" });
    gsap.to([ui.bossHint.hand_1.position, ui.bossHint.hand_2.position], { duration: 0.3, y: -1, ease: "power2.in", onComplete() {
      mainScene.remove(ui.bossHint, ui.finalCount, ui.bossCount);
    } });
  }
  if (hero[chosenHero].powerCount <= 0) 
  {
    const deadSound = atlas.play("20");
    atlas.volume(0.7, deadSound);
  }
  atlas.fade(0.6, 0.3, 200, soundID.game);
  setTimeout(() => {
  	if (hero[chosenHero].powerCount > 0) {
  	
  	  
  		currentLevel++;
  		sdk.setProgress(currentLevel);
  		goSaveData();
  		button[1].text.geometry.dispose();
  		button[1].text.geometry = new THREE.ShapeGeometry(RubikMonoOne.generateShapes(goLevelButtonText[currentLang] + ` ${currentLevel + 1}`, 0.048), 3);
  	  button[1].text.geometry.center();
  	  showWin();
  	} else {
  		showFail();
  	}
  }, 1000);
}





function clearLevel() {
	onPlay = false;
	gameContainer.remove(hero[chosenHero]);
	for (let i = 0; i < videoBonus.length; i++) {
	  videoBonus[i].ready = -1;
		if (videoBonus[i].leftTween !== undefined && videoBonus[i].leftTween !== null) {
	  	videoBonus[i].leftTween.kill();
	  	videoBonus[i].leftTween = null;
	  	videoBonus[i].rightTween.kill();
	  	videoBonus[i].rightTween = null;
		  videoBonus[i].valTween.kill();
	  	videoBonus[i].valTween = null;
		}
		if (videoBonus[i].sparkleScaleTween[0] !== undefined && videoBonus[i].sparkleScaleTween[0] !== null) {
	  	for (let k = 2; k < 10; k++) {
		  	videoBonus[i].sparkleScaleTween[k].kill();
		  	videoBonus[i].sparkleScaleTween[k] = null;
		  	videoBonus[i].sparkleMoveTween[k].kill();
		  	videoBonus[i].sparkleMoveTween[k] = null;
	  	}
		}
		if (videoBonus[i].ringTween_1 !== undefined && videoBonus[i].ringTween_1 !== null) {
	  	videoBonus[i].ringTween_1.kill();
  		videoBonus[i].ringTween_1 = null;
		  videoBonus[i].ringTween_2.kill();
		  videoBonus[i].ringTween_2 = null;
		}
		gameContainer.levelContainer.remove(videoBonus[i]);
	}
	for (let i = 0; i < food.length; i++) {
		if (food[i].rotTween !== undefined && food[i].rotTween !== null) {
		  food[i].rotTween.kill();
		}
		gameContainer.levelContainer.remove(food[i]);
	}
	for (let i = 0; i < coin.length; i++) {
		coin[i].ready == -1;
		if (coin[i].rotTween !== undefined && coin[i].rotTween !== null) {
		  coin[i].rotTween.kill();
		}
		gameContainer.levelContainer.remove(coin[i]);
	}
	for (let i = 0; i < basicBonus.length; i++) {
		basicBonus[i].ready = -1;
		if (basicBonus[i].leftTween !== undefined && basicBonus[i].leftTween !== null) {
	  	basicBonus[i].leftTween.kill();
	  	basicBonus[i].leftTween = null;
	  	basicBonus[i].rightTween.kill();
	  	basicBonus[i].rightTween = null;
	  	basicBonus[i].valTween.kill();
	  	basicBonus[i].valTween = null;
		}
		if (basicBonus[i].sparkleScaleTween[0] !== undefined && basicBonus[i].sparkleScaleTween[0] !== null) {
	  	for (let k = 2; k < 10; k++) {
		  	basicBonus[i].sparkleScaleTween[k].kill();
			  basicBonus[i].sparkleScaleTween[k] = null;
		  	basicBonus[i].sparkleMoveTween[k].kill();
		  	basicBonus[i].sparkleMoveTween[k] = null;
	  	}
		}
		if (basicBonus[i].ringTween_1 !== undefined && basicBonus[i].ringTween_1 !== null) {
	  	basicBonus[i].ringTween_1.kill();
	  	basicBonus[i].ringTween_1 = null;
	  	basicBonus[i].ringTween_2.kill();
	  	basicBonus[i].ringTween_2 = null;
		}
		gameContainer.levelContainer.remove(basicBonus[i]);
	}
	for (let i = 0; i < bomb.length; i++) {
		bomb[i].ready = -1;
		gameContainer.levelContainer.remove(bomb[i]);
	}
	for (let i = 0; i < 10; i++) {
		gameContainer.levelContainer.remove(gameContainer.punchFX[i]);
	}
	for (let i = 0; i < npc.length; i++) {
	  clearHeroAnimation(npc[i].children[0]);
	  if (npc[i].children[0].turnTween !== undefined && npc[i].children[0].turnTween !== null) {
	  	npc[i].children[0].turnTween.kill();
	  	npc[i].children[0].turnTween = null;
	  }
	}
	npc = [];
	for (let i = 0; i < npcGuard.length; i++) {
		if (!npcGuard[i].bonus) {
		  clearHeroAnimation(npcGuard[i].children[0]);
		} else {
			if (npcGuard[i].sparkleScaleTween[0] !== undefined && npcGuard[i].sparkleScaleTween[0] !== null) {
      	for (let k = 2; k < 10; k++) {
    	  	npcGuard[i].sparkleScaleTween[k].kill();
    	  	npcGuard[i].sparkleScaleTween[k] = null;
    	  	npcGuard[i].sparkleMoveTween[k].kill();
    	  	npcGuard[i].sparkleMoveTween[k] = null;
      	}
			}
			if (npcGuard[i].ringTween_1 !== undefined && npcGuard[i].ringTween_1 !== null) {
        npcGuard[i].ringTween_1.kill();
        npcGuard[i].ringTween_1 = null;
        npcGuard[i].ringTween_2.kill();
        npcGuard[i].ringTween_2 = null;
			}
		}
	}
	npcGuard = [];
	borderBox = [];
	gameContainer.bridge = [];
	gameContainer.arena = [];
	clearHeroAnimation(gameContainer.boss.children[0]);
	gameContainer.levelContainer.remove(gameContainer.bonusHeart);
  topContainer.remove(ui.livesContainer);
  mainScene.remove(gameContainer, ui.heroCount);
  disposeObject(gameContainer.levelContainer);
  gameContainer.add(gameContainer.levelContainer);
}
