function disposeObject(obj) {
	if (obj.children.length > 0) {
		for (let x = obj.children.length - 1; x >= 0; x--) {
			disposeObject(obj.children[x])
		}
	}
	if (obj.isMesh) {
		obj.geometry.dispose();
		obj.material.dispose();
	}
	if (obj.parent) {
		obj.parent.remove(obj)
	}
}
