	atlas.volume(0.25, winSound);
	atlas.fade(0.6, 0.3, 500, soundID.game);
  gsap.to(ui.fade.material, { duration: 0.6, opacity: 0.8, ease: "power1.inOut" });
  ui.fade.position.z = -1.1;
  moneyCount += levelMoney;
